import { expect, test } from "bun:test"
import type { AgentRelayState } from "../src/shared/protocol"
import { installChrome, settle, type StubEvent } from "./chrome-stub"

// The bundled pairing file (relay-pairing.json, the one-time code `install` writes into an unpacked build) is looked
// for again while the extension is unpaired, and re-read on Reconnect and when the entered code changes. No relay: WebSocket is
// a fake that never opens unless told to. The fakes stay installed after this file: the relay it creates keeps its
// timers for the rest of the run, and must never reach a real port.

const stub = installChrome()
;(globalThis as { __OPENCODE_BROWSER_BUILD__?: string }).__OPENCODE_BROWSER_BUILD__ = "test"

class FakeWebSocket {
  static readonly CONNECTING = 0
  static readonly OPEN = 1
  static readonly CLOSING = 2
  static readonly CLOSED = 3
  static readonly made: FakeWebSocket[] = []
  readyState = FakeWebSocket.CONNECTING
  onopen: ((event: unknown) => void) | null = null
  onmessage: ((event: unknown) => void) | null = null
  onclose: ((event: unknown) => void) | null = null
  constructor(readonly url: string) {
    FakeWebSocket.made.push(this)
  }
  sent: string[] = []
  send(message: string) { this.sent.push(message) }
  close(code = 1006, reason = "") {
    if (this.readyState === FakeWebSocket.CLOSED) return
    this.readyState = FakeWebSocket.CLOSED
    queueMicrotask(() => this.onclose?.({ code, reason, wasClean: false }))
  }
}

const CODE = "0123ABCD"
const OTHER = "ZYXW9876"
let bundled: string | undefined
const reads: string[] = []
const realFetch = globalThis.fetch
globalThis.fetch = (async (input: string | URL) => {
  const url = String(input)
  if (!url.endsWith("/relay-pairing.json")) return realFetch(input)
  reads.push(url)
  return bundled === undefined ? new Response("not found", { status: 404 }) : Response.json({ code: bundled })
}) as typeof fetch
;(globalThis as { WebSocket: unknown }).WebSocket = FakeWebSocket

await stub.chrome.storage.local.set({ agentRelayPort: 19925 })
const { createAgentRelay } = await import("../src/background/agent-relay")
const states: AgentRelayState[] = []
const relay = createAgentRelay({ changed: (state) => states.push(state), badgesChanged: () => {} })
const until = async (check: () => boolean) => {
  for (let i = 0; i < 100 && !check(); i++) await settle()
  expect(check()).toBe(true)
}
const alarm = () => (chrome.alarms.onAlarm as unknown as StubEvent).emit({ name: "opencode-browser-relay" })

test("without a pairing file, the extension sends only anonymous protocol presence", async () => {
  await until(() => relay.state().status === "unpaired")
  expect(relay.state().pairing).toBe("none")
  const socket = FakeWebSocket.made[0]!
  socket.readyState = FakeWebSocket.OPEN
  socket.onopen?.({})
  expect(socket.sent.map(s => JSON.parse(s))).toEqual([{ method: "protocol", params: { protocolVersion: 3, unpaired: true } }])
  socket.close(1000, "Waiting for pairing")
  await settle()
  expect(reads.length).toBeGreaterThan(0)
})

test("a pairing file written later (bun run setup) is found on the next attempt, without a worker restart", async () => {
  const before = reads.length
  bundled = CODE
  alarm()
  await until(() => FakeWebSocket.made.length === 2)
  expect(reads.length).toBe(before + 1)
  expect(relay.state().pairing).toBe("code")
  expect(relay.state().unpacked).toBe(true)
  expect(FakeWebSocket.made.at(-1)!.url).toBe("ws://127.0.0.1:19925/extension")
})

test("a found file is cached between attempts, and read again on Reconnect", async () => {
  // The relay isn't there: the attempt closes and backs off.
  FakeWebSocket.made.at(-1)!.close()
  await settle()
  const before = reads.length
  alarm()
  await settle()
  // A retry is scheduled, so the alarm leaves it alone; either way nothing re-reads a found file.
  expect(reads.length).toBe(before)
  bundled = OTHER
  relay.reconnect()
  await until(() => FakeWebSocket.made.length === 3)
  expect(reads.length).toBe(before + 1)
})

test("a pairing change re-reads the file", async () => {
  const before = reads.length
  bundled = undefined
  await stub.chrome.storage.local.set({ agentRelayPairingCode: CODE })
  await until(() => reads.length === before + 1)
  // No file now; the entered code takes over.
  await until(() => relay.state().pairing === "code" && relay.state().unpacked !== true)
})

test("a relay address that isn't one is refused, and nothing is saved", async () => {
  const before = FakeWebSocket.made.length
  expect(await relay.connectTo("host/path", "")).toEqual({ status: "invalid-address" })
  expect(await relay.connectTo("100.64.0.2", "not a pairing code")).toEqual({ status: "invalid-code" })
  // The long code earlier versions printed isn't one to type anymore.
  expect(await relay.connectTo("100.64.0.2", "0123")).toEqual({ status: "invalid-code" })
  expect((await stub.chrome.storage.local.get("agentRelayAddress")).agentRelayAddress).toBeUndefined()
  expect(FakeWebSocket.made).toHaveLength(before)
})

test("Connect dials the relay address, a typed code wins over the bundled one there, and the outcome comes back", async () => {
  bundled = OTHER
  const before = FakeWebSocket.made.length
  const outcome = relay.connectTo("100.64.0.2", CODE)
  await until(() => FakeWebSocket.made.length > before && FakeWebSocket.made.at(-1)!.url === "ws://100.64.0.2:19925/extension")
  expect(relay.state().relay).toEqual({ address: "100.64.0.2:19925", remote: true })
  expect(relay.state().pairing).toBe("code")
  // No relay answers there.
  FakeWebSocket.made.at(-1)!.close()
  expect(await outcome).toEqual({ status: "offline", address: "100.64.0.2:19925" })
  expect((await stub.chrome.storage.local.get("agentRelayAddress")).agentRelayAddress).toBe("100.64.0.2")
})

test("localhost (as the page shows it) goes back to this computer's relay and its bundled code", async () => {
  await stub.chrome.storage.local.remove("agentRelayPairingCode")
  for (const address of ["localhost:19925", "", "127.0.0.1"]) {
    await stub.chrome.storage.local.set({ agentRelayAddress: "100.64.0.2" })
    await settle()
    const before = FakeWebSocket.made.length
    const outcome = relay.connectTo(address, "")
    await until(() => FakeWebSocket.made.length > before && FakeWebSocket.made.at(-1)!.url === "ws://127.0.0.1:19925/extension")
    expect(relay.state().relay).toEqual({ address: "localhost:19925", remote: false })
    await until(() => relay.state().unpacked === true)
    expect((await stub.chrome.storage.local.get("agentRelayAddress")).agentRelayAddress).toBe("")
    FakeWebSocket.made.at(-1)!.close()
    expect((await outcome).status).toBe("offline")
  }
})

import { beforeEach, describe, expect, test } from "bun:test"
import { installChrome, settle } from "./chrome-stub"

const stub = installChrome()
const { AgentWindow } = await import("../src/background/agent-relay/window")

/** The user's window, focused, at the given bounds. */
async function userWindow(bounds: { left: number; top: number; width: number; height: number }) {
  const window = await stub.chrome.windows.create({ ...bounds, focused: true })
  stub.state.created.length = 0
  return window
}

beforeEach(async () => {
  stub.state.windows.clear()
  stub.state.tabs.clear()
  stub.state.created.length = 0
  stub.state.activations.length = 0
  stub.state.focusedWindowId = undefined
  stub.state.displays = [{ left: 0, top: 0, width: 1512, height: 982 }]
  await stub.chrome.storage.session.remove("agentWindowId")
  await stub.chrome.storage.local.remove("agentTabsWindow")
})

describe("AgentWindow.open", () => {
  test("by default opens a background tab in the window the user last focused", async () => {
    const user = await userWindow({ left: 0, top: 30, width: 1512, height: 950 })
    const userTab = [...stub.state.tabs.values()].find((tab) => tab.windowId === user.id)!
    const tab = await AgentWindow.open("https://example.com/")
    expect(tab.windowId).toBe(user.id)
    expect(tab.active).toBe(false)
    expect(stub.state.created).toHaveLength(0)
    expect(stub.state.tabs.get(userTab.id)!.active).toBe(true)
    expect(stub.state.focusedWindowId).toBe(user.id)
    expect(stub.state.activations).toEqual([])
  })

  test("with only a popup window focused, opens in an unfocused new window, never a focused one", async () => {
    await stub.chrome.windows.create({ type: "popup", focused: true })
    stub.state.created.length = 0
    const tab = await AgentWindow.open("https://example.com/")
    expect(stub.state.created).toEqual([expect.objectContaining({ focused: false, type: "normal" })])
    expect(stub.state.windows.get(tab.windowId)?.focused).toBe(false)
  })

  test("with no window at all, makes one unfocused", async () => {
    const tab = await AgentWindow.open("https://example.com/")
    expect(stub.state.created).toEqual([expect.objectContaining({ focused: false, type: "normal" })])
    expect(stub.state.windows.get(tab.windowId)?.focused).toBe(false)
    expect(await AgentWindow.id()).toBeUndefined()
  })

  test("the separate setting opens tabs in the agent window", async () => {
    await stub.chrome.storage.local.set({ agentTabsWindow: "separate" })
    const user = await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    const tab = await AgentWindow.open("https://example.com/")
    expect(tab.windowId).not.toBe(user.id)
    expect(tab.windowId).toBe((await AgentWindow.id())!)
    expect(stub.state.created).toEqual([expect.objectContaining({ focused: false })])
    expect(stub.state.focusedWindowId).toBe(user.id)
    expect(stub.state.activations).toEqual([])
  })

  test("an override from the relay wins over the setting, and switching affects new tabs only", async () => {
    const user = await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    const separate = await AgentWindow.open("https://example.com/1", { override: "separate" })
    expect(separate.windowId).not.toBe(user.id)
    await stub.chrome.storage.local.set({ agentTabsWindow: "separate" })
    const current = await AgentWindow.open("https://example.com/2", { override: "current" })
    expect(current.windowId).toBe(user.id)
    await stub.chrome.storage.local.set({ agentTabsWindow: "current" })
    expect((await AgentWindow.open("https://example.com/3")).windowId).toBe(user.id)
    // The tab already in the agent window stays there.
    expect(stub.state.tabs.get(separate.id!)!.windowId).toBe(separate.windowId)
  })

  test("an unknown stored value means the default", async () => {
    await stub.chrome.storage.local.set({ agentTabsWindow: "elsewhere" })
    expect(await AgentWindow.placement()).toBe("current")
  })
})

describe("AgentWindow.openTab", () => {
  test("makes one unfocused window beside the user's, then opens background tabs in it", async () => {
    // A second display to the right of the laptop screen.
    stub.state.displays.push({ left: 1512, top: 0, width: 2560, height: 1440 })
    const user = await userWindow({ left: 0, top: 30, width: 1512, height: 950 })

    const first = await AgentWindow.openTab("https://example.com/")
    expect(stub.state.created).toHaveLength(1)
    expect(stub.state.created[0]).toMatchObject({ focused: false, state: "normal", left: 1512, top: 30, width: 1280, height: 900 })
    expect(first.windowId).not.toBe(user.id)
    expect(stub.state.focusedWindowId).toBe(user.id)

    const second = await AgentWindow.openTab("https://example.org/")
    expect(stub.state.created).toHaveLength(1)
    expect(second.windowId).toBe(first.windowId)
    expect(second.active).toBe(false)
    expect(await AgentWindow.id()).toBe(first.windowId)
  })

  test("concurrent calls share one new window", async () => {
    await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    const tabs = await Promise.all([1, 2, 3].map((n) => AgentWindow.openTab(`https://example.com/${n}`)))
    expect(stub.state.created).toHaveLength(1)
    expect(new Set(tabs.map((tab) => tab.windowId)).size).toBe(1)
  })

  test("makes the window again after the user closes it", async () => {
    await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    const first = await AgentWindow.openTab("https://example.com/")
    await stub.chrome.windows.remove(first.windowId)
    await settle()
    expect(await AgentWindow.id()).toBeUndefined()
    const again = await AgentWindow.openTab("https://example.com/")
    expect(again.windowId).not.toBe(first.windowId)
    expect(stub.state.created).toHaveLength(2)
  })

  test("a stored id of a window that's gone (another browser session) isn't reused", async () => {
    await stub.chrome.storage.session.set({ agentWindowId: 9999 })
    await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    await AgentWindow.openTab("https://example.com/")
    expect(stub.state.created).toHaveLength(1)
  })

  test("tries the left when there's no room on the right", async () => {
    stub.state.displays = [{ left: 0, top: 0, width: 2560, height: 1440 }]
    await userWindow({ left: 1500, top: 100, width: 1060, height: 1000 })
    await AgentWindow.openTab("https://example.com/")
    // Right: entirely off the screen, refused by Chrome; left fits.
    expect(stub.state.created.map(({ left, top }) => ({ left, top }))).toEqual([
      { left: 2560, top: 100 },
      { left: 220, top: 100 },
    ])
  })

  test("lets Chrome place it when no side has room (one screen the user's window fills)", async () => {
    await userWindow({ left: 0, top: 30, width: 1512, height: 950 })
    const tab = await AgentWindow.openTab("https://example.com/")
    expect(stub.state.created).toHaveLength(5)
    expect(stub.state.created.at(-1)).toMatchObject({ focused: false, width: 1280, height: 900 })
    expect(stub.state.created.at(-1)?.left).toBeUndefined()
    expect(stub.state.windows.get(tab.windowId)?.focused).toBe(false)
  })

  test("without a focused window, opens with its size only", async () => {
    await AgentWindow.openTab("https://example.com/")
    expect(stub.state.created).toEqual([expect.objectContaining({ focused: false, width: 1280, height: 900 })])
    expect(stub.state.created[0]?.left).toBeUndefined()
  })
})

describe("AgentWindow.placements", () => {
  test("right, left, below, above the user's window", () => {
    expect(AgentWindow.placements({ left: 100, top: 50, width: 800, height: 600 }, { width: 400, height: 300 })).toEqual([
      { left: 900, top: 50, width: 400, height: 300 },
      { left: -300, top: 50, width: 400, height: 300 },
      { left: 100, top: 650, width: 400, height: 300 },
      { left: 100, top: -250, width: 400, height: 300 },
    ])
    expect(AgentWindow.placements({ left: 0 })).toEqual([])
  })
})

import { NodeHttpClient } from "@effect/platform-node"
import { Context, Effect, Layer, Match, Redacted, Schema } from "effect"
import * as AuthenticatedOriginInternal from "./auth/authenticated-origin.ts"
import * as RelayClient from "./relay/client.ts"
import * as RelayLifecycle from "./relay/lifecycle.ts"
import type {
  AuthenticatedJsonMethod,
  AuthenticatedJsonOutcome,
  SessionSummary,
} from "./relay/schema.ts"

export type Json = Schema.Schema.Type<typeof Schema.Json>

export class ClientError extends Schema.TaggedError<ClientError>()(
  "OpenCodeBrowserClient.Error",
  {
    message: Schema.String,
    reason: Schema.Literals(["connect", "session", "invalid-request"]),
    code: Schema.optionalKey(Schema.String),
    status: Schema.optionalKey(Schema.Number),
  },
) {}

export class OriginMismatch extends Schema.TaggedError<OriginMismatch>()(
  "AuthenticatedOrigin.OriginMismatch",
  {
    expectedOrigin: Schema.String,
    actualOrigin: Schema.String,
    message: Schema.String,
  },
) {}

export class HttpError extends Schema.TaggedError<HttpError>()(
  "AuthenticatedOrigin.HttpError",
  {
    status: Schema.Number,
    method: Schema.String,
    message: Schema.String,
  },
) {}

export class RequestFailed extends Schema.TaggedError<RequestFailed>()(
  "AuthenticatedOrigin.RequestFailed",
  {
    method: Schema.String,
    message: Schema.String,
  },
) {}

export class RequestOutcomeUnknown extends Schema.TaggedError<RequestOutcomeUnknown>()(
  "AuthenticatedOrigin.RequestOutcomeUnknown",
  {
    method: Schema.String,
    message: Schema.String,
  },
) {}

export class InvalidResponse extends Schema.TaggedError<InvalidResponse>()(
  "AuthenticatedOrigin.InvalidResponse",
  {
    reason: Schema.Literals(["invalid-json", "too-large"]),
    status: Schema.Number,
    maxResponseBytes: Schema.optionalKey(Schema.Number),
    message: Schema.String,
  },
) {}

export class ResponseDecodeFailed extends Schema.TaggedError<ResponseDecodeFailed>()(
  "AuthenticatedOrigin.ResponseDecodeFailed",
  {
    message: Schema.String,
  },
) {}

export class SensitiveCaptureActive extends Schema.TaggedError<SensitiveCaptureActive>()(
  "AuthenticatedOrigin.SensitiveCaptureActive",
  {
    message: Schema.String,
  },
) {}

export type Error =
  | ClientError
  | OriginMismatch
  | HttpError
  | RequestFailed
  | RequestOutcomeUnknown
  | InvalidResponse
  | ResponseDecodeFailed
  | SensitiveCaptureActive

export interface JsonOptions<S extends Schema.Top> {
  readonly path: `/${string}`
  readonly method?: AuthenticatedJsonMethod
  readonly headers?: Readonly<Record<string, string>>
  readonly body?: Json
  readonly response: S
  readonly sensitive?: boolean
  readonly handoffOnAuthFailure?: boolean
  readonly handoffMessage?: string
  readonly timeoutMs?: number
  readonly maxResponseBytes?: number
}

export interface AuthenticatedOriginCapability {
  readonly origin: string
  readonly json: {
    <S extends Schema.Top>(
      options: JsonOptions<S> & { readonly sensitive: true },
    ): Effect.Effect<Redacted.Redacted<S["Type"]>, Error, S["DecodingServices"]>
    <S extends Schema.Top>(
      options: JsonOptions<S> & { readonly sensitive?: false },
    ): Effect.Effect<S["Type"], Error, S["DecodingServices"]>
  }
}

export type AuthenticatedOrigin = AuthenticatedOriginCapability

/** Reveal a sensitive response using browse's Effect runtime. */
export const reveal = <A>(value: Redacted.Redacted<A>): A => Redacted.value(value)

export interface AuthenticatedOriginOptions {
  readonly origin: string
  /** Explicitly navigate here when the session page is not already on `origin`. */
  readonly startUrl?: string
  /** Default headers merged into every request on this origin. */
  readonly headers?: Readonly<Record<string, string>>
  /** Present an in-page handoff prompt and retry once if the session is logged out or redirected to auth. */
  readonly handoffOnAuthFailure?: boolean
  readonly handoffMessage?: string
}

export interface OriginClientOptions extends Omit<AuthenticatedOriginOptions, "origin"> {
  readonly session: string
  readonly readOnly?: boolean
  readonly endpoint?: string
}

export interface OriginClient {
  readonly origin: string
  readonly session: string
  readonly get: <T = unknown>(
    path: `/${string}`,
    options?: { readonly headers?: Readonly<Record<string, string>>; readonly timeoutMs?: number },
  ) => Promise<T>
  readonly post: <T = unknown>(
    path: `/${string}`,
    body?: Json,
    options?: { readonly headers?: Readonly<Record<string, string>>; readonly timeoutMs?: number },
  ) => Promise<T>
  readonly json: AuthenticatedOriginCapability["json"]
}

export interface Session {
  readonly id: string
  readonly summary: SessionSummary
  readonly authenticatedOrigin: (
    options: AuthenticatedOriginOptions,
  ) => Effect.Effect<AuthenticatedOriginCapability, ClientError>
}

export interface EnsureSessionOptions {
  readonly id: string
  readonly readOnly?: boolean
}

export interface Interface {
  readonly ensureSession: (
    options: EnsureSessionOptions,
  ) => Effect.Effect<Session, ClientError>
  readonly resetSession: (id: string) => Effect.Effect<Session, ClientError>
}

export interface MakeOptions {
  readonly endpoint?: string
}

export class Service extends Context.Service<Service, Interface>()(
  "opencode-browser-cli/OpenCodeBrowserClient",
) {}

export const make = Effect.fn("OpenCodeBrowserClient.make")(function* (options: MakeOptions = {}) {
  const relay = yield* RelayClient.make(options).pipe(
    Effect.provide(NodeHttpClient.layerNodeHttp),
    Effect.mapError((error) => clientError("connect", error)),
  )
  const readiness = yield* RelayLifecycle.ensureRelay({
    relay,
    // The consumer may run under Bun; the relay is a Node application.
    start: RelayLifecycle.startManagedRelay(undefined, "node", []),
  }).pipe(Effect.mapError((error) => clientError("connect", error)))
  if (readiness.buildProblem) {
    return yield* new ClientError({
      message: readiness.buildProblem,
      reason: "connect",
    })
  }
  yield* RelayLifecycle.ensureExtensionConnected({
    relay,
    waitForReconnect: true,
  }).pipe(Effect.mapError((error) => clientError("connect", error)))

  const ensureSession = Effect.fn("OpenCodeBrowserClient.ensureSession")(function* (
    sessionOptions: EnsureSessionOptions,
  ) {
    const summary = yield* relay.sessionEnsure(sessionOptions.id, {
      ...(sessionOptions.readOnly === undefined ? {} : { readOnly: sessionOptions.readOnly }),
    }).pipe(Effect.mapError((error) => clientError("session", error)))
    return makeSession(relay, summary)
  })

  const resetSession = Effect.fn("OpenCodeBrowserClient.resetSession")(function* (id: string) {
    const { session: summary } = yield* relay.sessionReset(id).pipe(
      Effect.mapError((error) => clientError("session", error)),
    )
    return makeSession(relay, summary)
  })

  return Service.of({ ensureSession, resetSession })
})

export const layer = (options: MakeOptions = {}): Layer.Layer<Service, ClientError> =>
  Layer.effect(Service, make(options))

export function origin(originUrl: string, options: OriginClientOptions): OriginClient {
  const normalizedOrigin = AuthenticatedOriginInternal.normalizeOrigin(originUrl)
  let cachedOrigin: Promise<AuthenticatedOriginCapability> | undefined
  const resolveOrigin = (): Promise<AuthenticatedOriginCapability> => {
    cachedOrigin ??= Effect.runPromise(
      Effect.gen(function* () {
        const client = yield* make(options.endpoint ? { endpoint: options.endpoint } : {})
        const liveSession = yield* client.ensureSession({
          id: options.session,
          ...(options.readOnly === undefined ? {} : { readOnly: options.readOnly }),
        })
        return yield* liveSession.authenticatedOrigin({
          origin: normalizedOrigin,
          startUrl: options.startUrl ?? "/",
          ...(options.headers ? { headers: options.headers } : {}),
          ...(options.handoffOnAuthFailure === undefined ? {} : { handoffOnAuthFailure: options.handoffOnAuthFailure }),
          ...(options.handoffMessage ? { handoffMessage: options.handoffMessage } : {}),
        })
      }),
    ).catch((error) => {
      cachedOrigin = undefined
      throw error
    })
    return cachedOrigin
  }
  const json: AuthenticatedOriginCapability["json"] = ((request: JsonOptions<Schema.Top>) =>
    Effect.promise(resolveOrigin).pipe(
      Effect.flatMap((cap) => cap.json(request as JsonOptions<Schema.Top> & { readonly sensitive?: false })),
    )) as AuthenticatedOriginCapability["json"]

  const callJson = async <T = unknown>(
    method: "GET" | "POST",
    path: `/${string}`,
    callOptions?: { readonly headers?: Readonly<Record<string, string>>; readonly timeoutMs?: number },
    body?: Json,
  ): Promise<T> => {
    const cap = await resolveOrigin()
    return (await Effect.runPromise(cap.json({
      path,
      method,
      ...(body === undefined ? {} : { body }),
      ...(callOptions?.headers ? { headers: callOptions.headers } : {}),
      ...(callOptions?.timeoutMs === undefined ? {} : { timeoutMs: callOptions.timeoutMs }),
      response: Schema.Json,
    }))) as T
  }

  return {
    origin: normalizedOrigin,
    session: options.session,
    get: <T = unknown>(path: `/${string}`, callOptions?: { readonly headers?: Readonly<Record<string, string>>; readonly timeoutMs?: number }) =>
      callJson<T>("GET", path, callOptions),
    post: <T = unknown>(path: `/${string}`, body?: Json, callOptions?: { readonly headers?: Readonly<Record<string, string>>; readonly timeoutMs?: number }) =>
      callJson<T>("POST", path, callOptions, body),
    json,
  }
}

function makeSession(relay: RelayClient.Interface, summary: SessionSummary): Session {
  return {
    id: summary.id,
    summary,
    authenticatedOrigin: (options) => Effect.try({
      try: () => makeAuthenticatedOrigin(relay, summary.id, options),
      catch: (cause) => cause instanceof ClientError
        ? cause
        : new ClientError({
            message: cause instanceof globalThis.Error ? cause.message : "Invalid authenticated origin",
            reason: "invalid-request",
          }),
    }),
  }
}

function makeAuthenticatedOrigin(
  relay: RelayClient.Interface,
  sessionId: string,
  options: AuthenticatedOriginOptions,
): AuthenticatedOrigin {
  const origin = AuthenticatedOriginInternal.normalizeOrigin(options.origin)
  const startUrl = options.startUrl === undefined ? undefined : AuthenticatedOriginInternal.resolveStartUrl(origin, options.startUrl)

  function json<S extends Schema.Top>(
    request: JsonOptions<S> & { readonly sensitive: true },
  ): Effect.Effect<Redacted.Redacted<S["Type"]>, Error, S["DecodingServices"]>
  function json<S extends Schema.Top>(
    request: JsonOptions<S> & { readonly sensitive?: false },
  ): Effect.Effect<S["Type"], Error, S["DecodingServices"]>
  function json<S extends Schema.Top>(
    request: JsonOptions<S>,
  ): Effect.Effect<S["Type"] | Redacted.Redacted<S["Type"]>, Error, S["DecodingServices"]> {
    const method = request.method ?? "GET"
    if (method === "GET" && request.body !== undefined) {
      return Effect.fail(new ClientError({
        message: "GET authenticated origin requests cannot include a body",
        reason: "invalid-request",
      }))
    }
    const mutation = method !== "GET"
    const mergedHeaders =
      options.headers || request.headers
        ? { ...(options.headers ?? {}), ...(request.headers ?? {}) }
        : undefined
    const handoffOnAuthFailure = request.handoffOnAuthFailure ?? options.handoffOnAuthFailure
    const handoffMessage = request.handoffMessage ?? options.handoffMessage
    return relay.authenticatedJson({
      sessionId,
      origin,
      ...(startUrl ? { startUrl } : {}),
      method,
      path: request.path,
      ...(mergedHeaders ? { headers: mergedHeaders } : {}),
      ...(request.body === undefined ? {} : { body: request.body }),
      ...(request.sensitive === true ? { sensitive: true } : {}),
      ...(handoffOnAuthFailure === undefined ? {} : { handoffOnAuthFailure }),
      ...(handoffMessage === undefined ? {} : { handoffMessage }),
      ...(request.timeoutMs === undefined ? {} : { timeoutMs: request.timeoutMs }),
      ...(request.maxResponseBytes === undefined ? {} : { maxResponseBytes: request.maxResponseBytes }),
    }).pipe(
      Effect.mapError((error): Error => mutation && (
          error instanceof RelayClient.RelayUnreachable || error instanceof RelayClient.RelayDecodeFailed
        )
        ? unknownOutcome(method)
        : clientError("session", error)),
      Effect.flatMap((outcome) => decodeOutcome(outcome, method, mutation, request)),
    )
  }

  return { origin, json }
}

function decodeOutcome<S extends Schema.Top>(
  outcome: AuthenticatedJsonOutcome,
  method: AuthenticatedJsonMethod,
  mutation: boolean,
  request: JsonOptions<S>,
): Effect.Effect<S["Type"] | Redacted.Redacted<S["Type"]>, Error, S["DecodingServices"]> {
  return Match.valueTags(outcome, {
    Success: (outcome) => {
      if (request.sensitive === true) {
        return Schema.decodeUnknownEffect(Schema.RedactedFromValue(request.response, {
          label: "browse authenticated response",
          disallowEncode: true,
        }))(outcome.value).pipe(
          Effect.mapError(() => mutation
            ? unknownOutcome(method)
            : new ResponseDecodeFailed({ message: "Sensitive authenticated response did not match the expected schema" })),
        )
      }
      return Schema.decodeUnknownEffect(request.response)(outcome.value).pipe(
        Effect.mapError((cause) => mutation
          ? unknownOutcome(method)
          : new ResponseDecodeFailed({ message: `Authenticated response did not match the expected schema: ${cause.message}` })),
      )
    },
    OriginMismatch: (outcome) =>
      Effect.fail(new OriginMismatch({
        expectedOrigin: outcome.expectedOrigin,
        actualOrigin: outcome.actualOrigin,
        message: `Session page origin ${outcome.actualOrigin} does not match ${outcome.expectedOrigin}`,
      })),
    HttpError: (outcome) =>
      Effect.fail(new HttpError({
        status: outcome.status,
        method,
        message: `Authenticated ${method} request was rejected with HTTP ${outcome.status}`,
      })),
    RequestFailed: (outcome) =>
      Effect.fail(mutation || outcome.outcome === "unknown"
        ? unknownOutcome(method)
        : new RequestFailed({ method, message: `Authenticated ${method} request failed before it was sent` })),
    InvalidJson: (outcome) =>
      Effect.fail(mutation
        ? unknownOutcome(method)
        : new InvalidResponse({
            reason: "invalid-json",
            status: outcome.status,
            message: "Authenticated response was not valid JSON",
          })),
    ResponseTooLarge: (outcome) =>
      Effect.fail(mutation
        ? unknownOutcome(method)
        : new InvalidResponse({
            reason: "too-large",
            status: outcome.status,
            maxResponseBytes: outcome.maxResponseBytes,
            message: `Authenticated response exceeded ${outcome.maxResponseBytes} bytes`,
          })),
    SensitiveCaptureActive: () =>
      Effect.fail(new SensitiveCaptureActive({
        message: "Sensitive authenticated requests are blocked while session network capture is active",
      })),
  })
}

function unknownOutcome(method: AuthenticatedJsonMethod): RequestOutcomeUnknown {
  return new RequestOutcomeUnknown({
    method,
    message: `Authenticated ${method} request outcome is unknown; reconcile state before retrying`,
  })
}

function clientError(reason: ClientError["reason"], error: unknown): ClientError {
  if (error instanceof ClientError) return error
  if (error instanceof RelayClient.RelayRejected) {
    return new ClientError({
      message: error.message,
      reason,
      status: error.status,
      ...(error.code ? { code: error.code } : {}),
    })
  }
  return new ClientError({
    message: error instanceof globalThis.Error ? error.message : "browse request failed",
    reason,
  })
}

import { afterEach, describe, expect, test } from "bun:test"
import { guardCdpMethod, scopeCdpResult } from "../src/cdp/guardrails.ts"

const pageUrls = () => ["https://app.example.com/dashboard", "chrome://newtab/"]
const cookies = [
  { name: "a", domain: "app.example.com" },
  { name: "b", domain: ".example.com" },
  { name: "c", domain: "bank.test" },
  { name: "d", domain: ".other.example.com" },
]

afterEach(() => {
  delete process.env.OPENCODE_BROWSER_ALLOW_ALL_STORAGE
  delete process.env.OPENCODE_BROWSER_ALLOW_FILE_URLS
  delete process.env.OPENCODE_BROWSER_ALLOW_ALL_COOKIES
  delete process.env.OPENCODE_BROWSER_ALLOW_FOREGROUND
})

describe("guardCdpMethod", () => {
  test("always blocks methods that destroy browser data", () => {
    for (const method of ["Network.clearBrowserCookies", "Storage.clearCookies", "Network.deleteCookies", "Storage.clearDataForOrigin", "Storage.clearDataForStorageKey", "Browser.close"]) {
      expect(guardCdpMethod({ method, readOnly: false })).toContain(`blocked ${method}`)
    }
  })

  test("always blocks WebAuthn: agents can't add virtual authenticators or answer passkey ceremonies", () => {
    for (const method of ["WebAuthn.enable", "WebAuthn.addVirtualAuthenticator", "WebAuthn.addCredential", "WebAuthn.getCredentials"]) {
      expect(guardCdpMethod({ method, readOnly: false })).toContain(`blocked ${method}`)
    }
  })

  test("blocks Page.bringToFront unless the relay allows foreground", () => {
    expect(guardCdpMethod({ method: "Page.bringToFront", readOnly: false })).toContain("Page.bringToFront")
    process.env.OPENCODE_BROWSER_ALLOW_FOREGROUND = "1"
    expect(guardCdpMethod({ method: "Page.bringToFront", readOnly: false })).toBeNull()
  })

  test("lets ordinary and custom relay methods through", () => {
    expect(guardCdpMethod({ method: "Page.navigate", readOnly: false })).toBeNull()
    expect(guardCdpMethod({ method: "Runtime.evaluate", readOnly: false })).toBeNull()
    expect(guardCdpMethod({ method: "OpenCodeBrowser.ghostCursor", readOnly: false })).toBeNull()
  })

  test("read-only sessions can take snapshots and screenshots", () => {
    for (const method of [
      // Snapshot and page reads.
      "Page.getFrameTree",
      "Page.getNavigationHistory",
      "Page.createIsolatedWorld",
      "Page.addScriptToEvaluateOnNewDocument",
      "Runtime.evaluate",
      "Runtime.callFunctionOn",
      "Runtime.getProperties",
      "Runtime.releaseObject",
      "Accessibility.getFullAXTree",
      "Accessibility.getPartialAXTree",
      "DOM.getDocument",
      "DOM.describeNode",
      "DOM.querySelectorAll",
      "DOM.getBoxModel",
      // Screenshots.
      "Page.captureScreenshot",
      "Page.getLayoutMetrics",
      // Page information and attachment.
      "Target.getTargets",
      "Target.getTargetInfo",
      "Target.attachToTarget",
      "Target.setAutoAttach",
      "Page.getResourceTree",
    ]) {
      expect(guardCdpMethod({ method, readOnly: true, sessionId: "look" })).toBeNull()
    }
  })

  test("read-only sessions may subscribe to events but nothing else", () => {
    for (const method of [
      "Page.enable", "Page.disable",
      "Runtime.enable", "Runtime.disable",
      "DOM.enable", "DOM.disable",
      "Accessibility.enable", "Accessibility.disable",
      "Network.enable", "Network.disable",
      "Log.enable", "Log.disable",
      "Performance.enable", "Performance.disable",
    ]) {
      expect(guardCdpMethod({ method, readOnly: true, sessionId: "look" })).toBeNull()
    }
    // Turning on request interception or spawning/attaching to a new target is not a read.
    for (const method of ["Fetch.enable", "Debugger.enable", "Cast.enable", "Overlay.enable"]) {
      expect(guardCdpMethod({ method, readOnly: true, sessionId: "look" })).toContain("this tab is read-only")
    }
  })

  test("read-only sessions cannot navigate, click or write cookies", () => {
    const refused = [
      { method: "Page.navigate", params: { url: "https://example.com/" } },
      { method: "Target.createTarget", params: { url: "https://example.com/" } },
      { method: "Target.closeTarget", params: { targetId: "TARGET" } },
      { method: "Input.dispatchMouseEvent", params: { type: "mousePressed", x: 1, y: 1 } },
      { method: "Input.dispatchKeyEvent", params: { type: "keyDown" } },
      { method: "Network.setCookie", params: { name: "x", value: "1", domain: "app.example.com" } },
      { method: "Storage.setCookies", params: { cookies: [{ name: "x", value: "1", domain: "app.example.com" }] } },
      { method: "Page.bringToFront" },
      { method: "Emulation.setScriptExecutionDisabled", params: { value: true } },
    ]
    for (const { method, params } of refused) {
      const message = guardCdpMethod({ method, readOnly: true, sessionId: "look", pageUrls, ...(params ? { params } : {}) })
      expect(message).toContain("Session look is read-only")
      expect(message).toContain("this tab is read-only")
      expect(message).toContain(method)
    }
  })

  test("writable sessions still allow interaction and cookie writes", () => {
    expect(guardCdpMethod({ method: "Input.dispatchMouseEvent", readOnly: false, pageUrls })).toBeNull()
    expect(guardCdpMethod({ method: "Page.navigate", readOnly: false, params: { url: "https://example.com/" } })).toBeNull()
    expect(guardCdpMethod({ method: "Target.createTarget", readOnly: false, params: { url: "https://example.com/" } })).toBeNull()
    expect(guardCdpMethod({ method: "Network.setCookie", readOnly: false, pageUrls, params: { name: "x", value: "1", domain: "app.example.com" } })).toBeNull()
    expect(guardCdpMethod({ method: "Runtime.evaluate", readOnly: false })).toBeNull()
  })

  test("browser permission grants are refused for every session", () => {
    for (const method of ["Browser.grantPermissions", "Browser.setPermission", "Browser.resetPermissions"]) {
      for (const readOnly of [false, true]) {
        const message = guardCdpMethod({ method, readOnly, sessionId: "look", params: { origin: "https://app.example.com", permissions: ["geolocation"] } })
        expect(message).toContain(`browse blocked ${method}`)
        expect(message).toContain("always blocked")
      }
    }
  })

  test("cookie writes are limited to the hosts of the session's pages", () => {
    const allowed = { method: "Network.setCookie", readOnly: false, pageUrls, params: { name: "x", value: "1", domain: ".example.com" } }
    expect(guardCdpMethod(allowed)).toBeNull()
    expect(guardCdpMethod({ ...allowed, params: { name: "x", value: "1", url: "https://app.example.com/" } })).toBeNull()
    expect(guardCdpMethod({ ...allowed, params: { name: "x", value: "1", domain: "bank.test" } })).toContain("bank.test")
    expect(guardCdpMethod({ ...allowed, params: { name: "x", value: "1" } })).toContain("without a domain")
    const batch = { method: "Storage.setCookies", readOnly: false, pageUrls, params: { cookies: [{ name: "x", domain: "app.example.com" }, { name: "y", domain: "evil.test" }] } }
    expect(guardCdpMethod(batch)).toContain("evil.test")
  })

  test("OPENCODE_BROWSER_ALLOW_ALL_COOKIES lifts the cookie write scope", () => {
    process.env.OPENCODE_BROWSER_ALLOW_ALL_COOKIES = "1"
    expect(guardCdpMethod({ method: "Network.setCookie", readOnly: false, pageUrls, params: { name: "x", domain: "bank.test" } })).toBeNull()
  })
})

describe("site storage scope", () => {
  const guard = (method: string, params?: Record<string, unknown>) => guardCdpMethod({ method, readOnly: false, pageUrls, ...(params ? { params } : {}) })

  test("storage of the session's page hosts is allowed", () => {
    expect(guard("IndexedDB.requestDatabaseNames", { securityOrigin: "https://app.example.com" })).toBeNull()
    expect(guard("IndexedDB.requestData", { storageKey: "https://app.example.com/", databaseName: "db", objectStoreName: "s", indexName: "", skipCount: 0, pageSize: 10 })).toBeNull()
    expect(guard("IndexedDB.getMetadata", { storageBucket: { storageKey: "https://app.example.com/", name: "default" }, databaseName: "db", objectStoreName: "s" })).toBeNull()
    expect(guard("CacheStorage.requestCacheNames", { storageKey: "https://app.example.com/" })).toBeNull()
    expect(guard("CacheStorage.requestEntries", { cacheId: "https://app.example.com/|v1", skipCount: 0, pageSize: 5 })).toBeNull()
    expect(guard("DOMStorage.getDOMStorageItems", { storageId: { securityOrigin: "https://app.example.com", isLocalStorage: true } })).toBeNull()
    expect(guard("Storage.getUsageAndQuota", { origin: "https://app.example.com" })).toBeNull()
    expect(guard("Storage.trackIndexedDBForStorageKey", { storageKey: "https://app.example.com/^0https://example.com" })).toBeNull()
    expect(guard("Storage.getStorageKeyForFrame", { frameId: "F" })).toBeNull()
    expect(guard("IndexedDB.enable")).toBeNull()
  })

  test("other origins' storage is refused", () => {
    expect(guard("IndexedDB.requestDatabaseNames", { securityOrigin: "https://bank.test" })).toContain("bank.test")
    // Exact hosts: storage is per origin, so a sibling or parent domain is another site's storage.
    expect(guard("IndexedDB.requestDatabaseNames", { securityOrigin: "https://example.com" })).toContain("blocked")
    expect(guard("IndexedDB.requestData", { storageKey: "https://bank.test/", databaseName: "db" })).toContain("blocked")
    expect(guard("IndexedDB.deleteDatabase", { storageBucket: { storageKey: "https://bank.test/", name: "default" }, databaseName: "db" })).toContain("blocked")
    expect(guard("CacheStorage.requestEntries", { cacheId: "https://bank.test/|v1" })).toContain("blocked")
    expect(guard("DOMStorage.getDOMStorageItems", { storageId: { storageKey: "https://bank.test/", isLocalStorage: true } })).toContain("blocked")
    expect(guard("Storage.getUsageAndQuota", { origin: "https://bank.test" })).toContain("blocked")
    expect(guard("Storage.trackCacheStorageForOrigin", { origin: "https://bank.test" })).toContain("blocked")
    expect(guard("Storage.getSharedStorageEntries", { ownerOrigin: "https://bank.test" })).toContain("blocked")
    expect(guard("Storage.getInterestGroupDetails", { ownerOrigin: "https://ads.test", name: "x" })).toContain("blocked")
    expect(guard("ServiceWorker.unregister", { scopeURL: "https://bank.test/" })).toContain("blocked")
    // A mixed request (the session's origin in one field, another in another) is refused too.
    expect(guard("IndexedDB.requestDatabaseNames", { securityOrigin: "https://app.example.com", storageKey: "https://bank.test/" })).toContain("blocked")
    // So is one that names no origin, and one that reads every origin.
    expect(guard("IndexedDB.requestDatabaseNames", {})).toContain("names no origin")
    expect(guard("Storage.getTrustTokens")).toContain("every site")
    expect(guard("Storage.setInterestGroupTracking", { enable: true })).toContain("blocked")
  })

  test("a session without web pages reaches no storage, unless the relay allows it", () => {
    expect(guardCdpMethod({ method: "IndexedDB.requestDatabaseNames", readOnly: false, pageUrls: () => ["about:blank"], params: { securityOrigin: "https://app.example.com" } })).toContain("none")
    process.env.OPENCODE_BROWSER_ALLOW_ALL_STORAGE = "1"
    expect(guard("IndexedDB.requestDatabaseNames", { securityOrigin: "https://bank.test" })).toBeNull()
    expect(guard("Storage.getTrustTokens")).toBeNull()
  })

  test("DevTools' resource loader reaches only the session's page hosts", () => {
    expect(guard("Network.loadNetworkResource", { frameId: "F", url: "https://app.example.com/app.js.map", options: {} })).toBeNull()
    expect(guard("Network.loadNetworkResource", { frameId: "F", url: "https://bank.test/api/me", options: {} })).toContain("blocked")
    expect(guard("Network.loadNetworkResource", { frameId: "F", url: "file:///etc/passwd", options: {} })).toContain("blocked")
  })

  test("cookie methods keep their own scope", () => {
    expect(guard("Storage.getCookies")).toBeNull()
    expect(guard("Storage.setCookies", { cookies: [{ name: "x", domain: "app.example.com" }] })).toBeNull()
  })
})

describe("navigation scope", () => {
  const navigate = (method: string, url: string) => guardCdpMethod({ method, readOnly: false, params: { url } })

  test("browser-internal pages, other extensions, DevTools and files are refused", () => {
    for (const url of [
      "file:///etc/passwd",
      "FILE:///Users/someone/.ssh/id_rsa",
      " file:///etc/hosts",
      "chrome://settings",
      "chrome-extension://aaaabbbbccccddddeeeeffffgggghhhh/popup.html",
      "chrome-untrusted://terminal/",
      "devtools://devtools/bundled/inspector.html",
      "view-source:https://example.com/",
      "edge://settings",
    ]) {
      expect(navigate("Page.navigate", url)).toContain("blocked Page.navigate")
      expect(navigate("Target.createTarget", url)).toContain("blocked Target.createTarget")
    }
  })

  test("web, data and about URLs are allowed", () => {
    for (const url of ["https://example.com/", "http://localhost:3000/", "data:text/html,<h1>hi</h1>", "about:blank", "blob:https://example.com/x"]) {
      expect(navigate("Page.navigate", url)).toBeNull()
      expect(navigate("Target.createTarget", url)).toBeNull()
    }
  })

  test("OPENCODE_BROWSER_ALLOW_FILE_URLS allows file: only", () => {
    process.env.OPENCODE_BROWSER_ALLOW_FILE_URLS = "1"
    expect(navigate("Page.navigate", "file:///tmp/report.html")).toBeNull()
    expect(navigate("Page.navigate", "chrome://settings")).toContain("blocked")
  })
})

describe("scopeCdpResult", () => {
  test("cookie reads return only cookies sent to the session's pages", () => {
    for (const method of ["Storage.getCookies", "Network.getAllCookies", "Network.getCookies"]) {
      const result = scopeCdpResult({ method, result: { cookies }, pageUrls })
      expect(result.cookies.map((cookie) => cookie.name)).toEqual(["a", "b"])
    }
  })

  test("a session without web pages sees no cookies", () => {
    expect(scopeCdpResult({ method: "Storage.getCookies", result: { cookies }, pageUrls: () => ["about:blank"] }).cookies).toEqual([])
  })

  test("other results and the escape hatch pass through", () => {
    const result = { cookies }
    expect(scopeCdpResult({ method: "Page.getFrameTree", result, pageUrls })).toBe(result)
    process.env.OPENCODE_BROWSER_ALLOW_ALL_COOKIES = "1"
    expect(scopeCdpResult({ method: "Storage.getCookies", result, pageUrls }).cookies).toHaveLength(4)
  })
})

import { describe, expect, test } from "bun:test"
import { checkNavigationUrl, checkUrl, explicitlyAllowsHost, isPrivateAddress, normalizeOriginPatterns, OriginPatternError, parseOriginPatterns } from "../src/auth/domain-policy.ts"

const rules = (...patterns: string[]) => parseOriginPatterns(patterns)

describe("origin patterns", () => {
  test("bare hosts, wildcards, origins and ports", () => {
    const allow = rules("example.com", "*.shop.test", "https://secure.test", "dev.test:8080")
    expect(checkUrl("https://example.com/a", allow).allowed).toBe(true)
    expect(checkUrl("http://example.com:81/", allow).allowed).toBe(true)
    expect(checkUrl("https://www.example.com/", allow).allowed).toBe(false)
    expect(checkUrl("https://shop.test/", allow).allowed).toBe(true)
    expect(checkUrl("https://a.b.shop.test/", allow).allowed).toBe(true)
    expect(checkUrl("https://evilshop.test/", allow).allowed).toBe(false)
    expect(checkUrl("https://secure.test/", allow).allowed).toBe(true)
    expect(checkUrl("http://secure.test/", allow).allowed).toBe(false)
    expect(checkUrl("https://secure.test:444/", allow).allowed).toBe(false)
    expect(checkUrl("http://dev.test:8080/", allow).allowed).toBe(true)
    expect(checkUrl("http://dev.test:8081/", allow).allowed).toBe(false)
  })

  test("about:, data: and blob: documents load nothing remote", () => {
    const allow = rules("example.com")
    expect(checkUrl("about:blank", allow).allowed).toBe(true)
    expect(checkUrl("data:text/html,hi", allow).allowed).toBe(true)
    expect(checkUrl("ftp://example.com/", allow).allowed).toBe(false)
  })

  test("refuses patterns that allow everything or carry paths", () => {
    expect(() => parseOriginPatterns(["*"])).toThrow(OriginPatternError)
    expect(() => parseOriginPatterns(["example.com/path"])).toThrow(OriginPatternError)
    expect(() => parseOriginPatterns(["ftp://example.com"])).toThrow(OriginPatternError)
    expect(() => parseOriginPatterns(["*.com.*"])).toThrow(OriginPatternError)
    expect(() => parseOriginPatterns(["*.10.0.0.1"])).toThrow(OriginPatternError)
    expect(normalizeOriginPatterns(["Example.com, *.Shop.test", "example.com"])).toEqual(["example.com", "*.shop.test"])
  })
})

describe("private addresses", () => {
  test("ranges", () => {
    for (const ip of ["127.0.0.1", "10.1.2.3", "172.16.0.1", "172.31.255.255", "192.168.1.1", "169.254.169.254", "100.64.0.1", "0.0.0.0", "::1", "fe80::1", "fd00::1", "::ffff:127.0.0.1", "::ffff:7f00:1"]) {
      expect(isPrivateAddress(ip)).toBe(true)
    }
    for (const ip of ["8.8.8.8", "172.32.0.1", "1.1.1.1", "2606:4700::1111"]) {
      expect(isPrivateAddress(ip)).toBe(false)
    }
  })

  test("wildcards never reach private hosts; naming the exact host does", () => {
    expect(checkUrl("http://web.app.localhost:3000/", rules("*.app.localhost")).allowed).toBe(false)
    expect(checkUrl("http://localhost:3000/", rules("localhost")).allowed).toBe(true)
    expect(checkUrl("http://localhost:3000/", rules("http://localhost:3000")).allowed).toBe(true)
    expect(checkUrl("http://127.0.0.1/", rules("127.0.0.1")).allowed).toBe(true)
    expect(explicitlyAllowsHost(rules("127.0.0.1"), "http://127.0.0.1:9/")).toBe(true)
    expect(explicitlyAllowsHost(rules("*.example.com"), "http://a.example.com/")).toBe(false)
  })

  test("decimal, hex and octal IPv4 spellings normalize before the check", async () => {
    const allow = rules("example.com")
    for (const url of ["http://2130706433/", "http://0x7f000001/", "http://0177.0.0.1/", "http://[::ffff:127.0.0.1]/"]) {
      const decision = checkUrl(url, allow)
      expect(decision.allowed).toBe(false)
    }
    expect((await checkNavigationUrl("http://2130706433/", rules("127.0.0.1"))).allowed).toBe(true)
  })

  test("a name that resolves to a private address needs an exact pattern", async () => {
    const decision = await checkNavigationUrl("http://localhost.:1/", rules("*.example.com"))
    expect(decision.allowed).toBe(false)
  })
})

import { afterAll, beforeAll, describe, expect, test } from "bun:test"
import fs from "node:fs"
import os from "node:os"
import path from "node:path"
import { checkHostCall, createExecuteFiles, ExecuteRealm, sandboxModules } from "../src/execute-realm.ts"
import { prepareExecuteFileOutputs } from "../src/execute-realm/file-roots.ts"

const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "browse-cdp-roots-"))
let previousHome: string | undefined

beforeAll(() => {
  previousHome = process.env.OPENCODE_BROWSER_HOME
  process.env.OPENCODE_BROWSER_HOME = path.join(scratch, "home")
  fs.mkdirSync(process.env.OPENCODE_BROWSER_HOME, { recursive: true })
})
afterAll(() => {
  if (previousHome === undefined) delete process.env.OPENCODE_BROWSER_HOME
  else process.env.OPENCODE_BROWSER_HOME = previousHome
  fs.rmSync(scratch, { recursive: true, force: true })
})

class CDPSession {
  readonly sent: Array<{ readonly method: unknown; readonly params: string | undefined }> = []
  async send(method: unknown, params?: unknown) {
    this.sent.push({ method, params: params === undefined ? undefined : JSON.stringify(params) })
    return "sent"
  }
  async detach() {}
}

function run(body: string, host: Record<string, unknown>) {
  return new ExecuteRealm().run({ source: `(async (host) => { ${body} })`, filename: "test.js", args: [host] })
}

function cdpHost(session: CDPSession) {
  return { browser: { async newBrowserCDPSession() { return session } }, context: { async newCDPSession() { return session } }, page: {} }
}

async function sendInRealm(method: string, params: string, session = new CDPSession()) {
  const result = await run(`
    const cdp = await host.browser.newBrowserCDPSession();
    try { await cdp.send(${method}, ${params}); return { sent: true } }
    catch (error) { return { error: error.message } }
  `, cdpHost(session))
  return { result: result as { readonly sent?: boolean; readonly error?: string }, session }
}

function checkCdp(method: string, params: unknown, session = new CDPSession()) {
  const args: unknown[] = [method, params]
  return { args, call: checkHostCall(session.send, session, args) }
}

describe("raw CDP send parameters", () => {
  test("toJSON functions anywhere in params are refused before the mock send runs", async () => {
    const cases = [
      ['"DOM.setFileInputFiles"', '{ files: [{ toJSON() { return "/etc/realm-denied" } }] }'],
      ['"Page.navigate"', '{ toJSON() { return { url: "https://example.com" } } }'],
      ['"Browser.setDownloadBehavior"', '{ behavior: "allow", downloadPath: { toJSON() { return "/etc/realm-denied" } } }'],
      ['"Page.navigate"', '() => ({ url: "https://example.com" })'],
      ['"Page.navigate"', 'Object.assign(() => ({}), { toJSON() { return { url: "https://example.com" } } })'],
    ] as const
    for (const [method, params] of cases) {
      const { result, session } = await sendInRealm(method, params)
      expect(result.error, method).toMatch(/plain JSON data/)
      expect(session.sent, method).toEqual([])
    }
  })

  test("boxed String method names are refused", async () => {
    const { result, session } = await sendInRealm('new String("DOM.setFileInputFiles")', '{ files: ["/etc/realm-denied"] }')
    expect(result.error).toMatch(/primitive string/)
    expect(session.sent).toEqual([])
  })

  test("file lists must be arrays of strings", async () => {
    const { result, session } = await sendInRealm('"DOM.setFileInputFiles"', '{ files: { 0: "/etc/realm-denied" } }')
    expect(result.error).toMatch(/must be an array of file paths/)
    expect(session.sent).toEqual([])
  })

  test("valid params are deep-copied and sent", () => {
    const params = { url: "https://example.com", nested: [1, true, null, "x"] }
    const { args } = checkCdp("Page.navigate", params)
    expect(args[1]).not.toBe(params)
    expect(args[1]).toEqual(params)
    expect(JSON.stringify(args[1])).toBe(JSON.stringify(params))
  })

  test("a normal CDP call still reaches the mock send", async () => {
    const { result, session } = await sendInRealm('"Page.navigate"', '{ url: "https://example.com" }')
    expect(result.sent).toBe(true)
    expect(session.sent).toEqual([{ method: "Page.navigate", params: '{"url":"https://example.com"}' }])
  })

  test("undefined object properties are omitted like JSON.stringify", async () => {
    const { result, session } = await sendInRealm('"Runtime.evaluate"', '{ expression: "1", contextId: undefined }')
    expect(result.sent).toBe(true)
    expect(session.sent).toEqual([{ method: "Runtime.evaluate", params: '{"expression":"1"}' }])
    const files = createExecuteFiles()
    const { args } = checkCdp("DOM.setFileInputFiles", { nodeId: 1, files: [files.path("upload.txt")], objectId: undefined })
    expect("objectId" in (args[1] as object)).toBe(false)
    expect(JSON.stringify(args[1])).toBe(JSON.stringify({ nodeId: 1, files: [files.path("upload.txt")] }))
  })

  test("undefined array elements are still refused", async () => {
    const { result, session } = await sendInRealm('"Page.navigate"', '{ urls: ["https://example.com", undefined] }')
    expect(result.error).toMatch(/arrays cannot contain undefined, use null/)
    expect(session.sent).toEqual([])
  })

  test("proxies, cycles and accessors are refused", () => {
    const session = new CDPSession()
    expect(() => checkCdp("Page.navigate", new Proxy({ url: "https://example.com" }, {}), session)).toThrow(/proxies/)
    const cycle: Record<string, unknown> = {}
    cycle.self = cycle
    expect(() => checkCdp("Page.navigate", cycle, session)).toThrow(/cyclical/)
    const accessor: Record<string, unknown> = {}
    Object.defineProperty(accessor, "url", { get: () => "https://example.com", enumerable: true })
    expect(() => checkCdp("Page.navigate", accessor, session)).toThrow(/getters, setters/)
  })
})

describe("raw CDP file inputs", () => {
  const files = createExecuteFiles()
  const inside = files.path("upload.txt")
  const root = files.roots[0]!
  const directory = path.join(files.dir, "upload-dir")
  fs.mkdirSync(directory, { recursive: true })

  test("DOM.setFileInputFiles, drag and PWA files refuse roots and directories", () => {
    const session = new CDPSession()
    const methods: Array<readonly [string, (value: string) => Record<string, unknown>]> = [
      ["DOM.setFileInputFiles", (value) => ({ files: [value] })],
      ["Input.dispatchDragEvent", (value) => ({ type: "drop", data: { files: [value] } })],
      ["PWA.launchFilesInApp", (value) => ({ manifestId: "app", files: [value] })],
    ]
    for (const [method, params] of methods) {
      expect(() => checkCdp(method, params(root), session), method).toThrow(/execute file root/)
      expect(() => checkCdp(method, params(directory), session), method).toThrow(/is a directory/)
      expect(() => checkCdp(method, params("/etc/realm-denied"), session), method).toThrow(/outside the execute file roots/)
      expect(() => checkCdp(method, params(inside), session), method).not.toThrow()
    }
  })

  test("file paths are written back resolved", () => {
    const path = `${files.dir}/nested/../upload.txt`
    const cases: Array<readonly [string, (files: string[]) => Record<string, unknown>, (params: unknown) => string[]]> = [
      ["DOM.setFileInputFiles", (files) => ({ files }), (params) => (params as { files: string[] }).files],
      ["Input.dispatchDragEvent", (files) => ({ type: "drop", data: { files } }), (params) => (params as { data: { files: string[] } }).data.files],
      ["PWA.launchFilesInApp", (files) => ({ manifestId: "app", files }), (params) => (params as { files: string[] }).files],
    ]
    for (const [method, params, filesOf] of cases) {
      const { args } = checkCdp(method, params([path]))
      expect(filesOf(args[1]), method).toEqual([inside])
    }
  })

  test("setInputFiles and setFiles refuse roots but keep directory support; drop refuses directories", () => {
    function setInputFiles() {}
    function setFiles() {}
    function drop() {}
    expect(() => checkHostCall(setInputFiles, {}, [root])).toThrow(/execute file root/)
    expect(() => checkHostCall(setInputFiles, {}, [directory])).not.toThrow()
    expect(() => checkHostCall(setFiles, {}, [root])).toThrow(/execute file root/)
    expect(() => checkHostCall(setFiles, {}, [directory])).not.toThrow()
    expect(() => checkHostCall(drop, {}, [{ files: [root] }])).toThrow(/execute file root/)
    expect(() => checkHostCall(drop, {}, [{ files: [directory] }])).toThrow(/is a directory/)
    expect(() => checkHostCall(drop, {}, [{ files: { name: "a.txt", mimeType: "text/plain", buffer: Buffer.from("a") } }])).not.toThrow()
  })
})

